--## MONITORS ###

--###############

-- See https://wiki.hypr.land/Configuring/Monitors/

--monitor=,preferred,auto,auto

hl.monitor({
    output   = "DP-2",
    mode     = "1920x1080@100",
    position = "0x0",
    scale    = 1,
})

hl.monitor({
    output   = "HDMI-A-1",
    mode     = "1366x768@59.79",
    position = "1920x0",
    scale    = 1,
})

-- Workspaces independientes por monitor con IDs UNICOS (la TV TCL es 720p nativa, no puede con 1080p real)

-- DP-2 (principal): 1-10 | HDMI-A-1 (TV): 11-20 con defaultName 1-10 (prefijo ZWSP U+200B para

-- que waybar muestre numeracion local sin colisionar con los nombres del DP).

-- OJO: Hyprland no permite el mismo ID persistente en dos monitores (las reglas por rango/ID

-- se pisan entre si), por eso el offset del HDMI.

hl.workspace_rule({
    workspace = 1,
    monitor = "DP-2",
    persistent = true,
})

