hl.on("hyprland.start", function()
    hl.exec_cmd("~/.config/waybar/scripts/start-waybar.sh")
    hl.exec_cmd("~/.config/waybar/scripts/audio-devices.sh --restore")
    hl.exec_cmd("test -x \"" .. os.getenv("HOME") .. "/.local/bin/fcitx5-no-tray\" && \"" .. os.getenv("HOME") .. "/.local/bin/fcitx5-no-tray\"")
    hl.exec_cmd("command -v awww-daemon >/dev/null 2>&1 && awww-daemon || command -v swww-daemon >/dev/null 2>&1 && swww-daemon")
    hl.exec_cmd("test -x/usr/lib/hyprpolkitagent/hyprpolkitagent &&/usr/lib/hyprpolkitagent/hyprpolkitagent")
    hl.exec_cmd("command -v hyprlauncher >/dev/null 2>&1 && hyprlauncher --daemon")
    hl.exec_cmd("swaync")
    hl.exec_cmd("qpwgraph")
    hl.exec_cmd("command -v swayosd-server >/dev/null 2>&1 && swayosd-server")
    hl.exec_cmd("command -v solaar >/dev/null 2>&1 && solaar -w hide")
    hl.exec_cmd("~/.config/control-center/lnx-control-center --daemon")
    hl.exec_cmd("~/.config/hypr/scripts/update-emoji-data.sh")
    hl.exec_cmd("wl-paste --type text --watch cliphist -max-items 20 store")
    hl.exec_cmd("wl-paste --type image --watch cliphist -max-items 20 store")
end)
